#include "../w4a16_layout.h"
#include "w4_integer_layout.h"

#include <acl/acl.h>
#include <pthread.h>
#include <stdlib.h>

/* C declaration of the launch stub generated by the Ascend C compiler. */
extern uint32_t aclrtlaunch_plait_ascend_w4a16(
    uint32_t blocks, aclrtStream stream, void *activation, void *weight, void *scale,
    void *zero, void *bias, void *output, uint32_t m, uint32_t n, uint32_t k,
    uint32_t group_size, uint32_t output_bits, uint32_t has_bias);
#if defined(PLAIT_ASCEND_INTEGER_CUBE)
extern uint32_t aclrtlaunch_plait_ascend_quantize_scales(
    uint32_t blocks, aclrtStream stream, void *input, void *scales,
    uint32_t rows, uint32_t k, uint32_t group_size, uint32_t bits);
extern uint32_t aclrtlaunch_plait_ascend_quantize_pack(
    uint32_t blocks, aclrtStream stream, void *input, void *scales, void *codes, void *invalid,
    uint32_t rows, uint32_t k, uint32_t group_size, uint32_t bits);
extern uint32_t aclrtlaunch_plait_ascend_pack_w4(
    uint32_t blocks, aclrtStream stream, void *activation, void *weight, void *zero,
    void *packed_a, void *packed_b, uint32_t m, uint32_t n, uint32_t k, uint32_t group_size,
    uint32_t padded_m, uint32_t padded_n, uint32_t padded_k, uint32_t bits);
extern uint32_t aclrtlaunch_plait_ascend_w4_cube(
    uint32_t blocks, aclrtStream stream, void *packed_a, void *packed_b, void *scratch,
    uint32_t m, uint32_t n, uint32_t k, uint32_t groups);
extern uint32_t aclrtlaunch_plait_ascend_finish_w4(
    uint32_t blocks, aclrtStream stream, void *activation, void *activation_scale, void *weight,
    void *weight_scale, void *zero, void *bias, void *scratch, void *output,
    uint32_t m, uint32_t n, uint32_t k, uint32_t group_size, uint32_t bits,
    uint32_t output_bits, uint32_t has_bias, uint32_t use_cube);
#endif

typedef struct {
    aclrtContext context;
    aclrtStream stream;
#if defined(PLAIT_ASCEND_INTEGER_CUBE)
    uint32_t cube_cores;
    uint32_t vector_cores;
#endif
} ascend_session;

typedef struct {
    aclrtEvent event;
    void *workspace;
} ascend_completion;

#if defined(PLAIT_ASCEND_INTEGER_CUBE)
static uint32_t device_cores(int ordinal, aclrtDevAttr attribute) {
    int64_t count = 0;
    if (aclrtGetDeviceInfo(ordinal, attribute, &count) != ACL_SUCCESS || count <= 0 ||
        count > UINT32_MAX) return 1;
    return (uint32_t)count;
}
#endif

static pthread_once_t initialized = PTHREAD_ONCE_INIT;
static aclError init_status;

static void initialize(void) {
    init_status = aclInit(NULL);
    if (init_status == ACL_ERROR_REPEAT_INITIALIZE) init_status = ACL_SUCCESS;
}

static int device_open(int ordinal, void **result) {
    if (pthread_once(&initialized, initialize) != 0) return ACL_ERROR_INTERNAL_ERROR;
    if (init_status != ACL_SUCCESS) return init_status;
    ascend_session *session = calloc(1, sizeof(*session));
    if (!session) return ACL_ERROR_BAD_ALLOC;
    aclError status = aclrtCreateContext(&session->context, ordinal);
    if (status == ACL_SUCCESS) {
        status = aclrtCreateStream(&session->stream);
        if (status != ACL_SUCCESS) aclrtDestroyContext(session->context);
    }
    if (status != ACL_SUCCESS) {
        free(session);
        return status;
    }
#if defined(PLAIT_ASCEND_INTEGER_CUBE)
    session->cube_cores = device_cores(ordinal, ACL_DEV_ATTR_CUBE_CORE_NUM);
    session->vector_cores = device_cores(ordinal, ACL_DEV_ATTR_VECTOR_CORE_NUM);
#endif
    *result = session;
    return ACL_SUCCESS;
}

static void device_close(void *handle) {
    ascend_session *session = handle;
    if (aclrtSetCurrentContext(session->context) == ACL_SUCCESS) {
        aclrtSynchronizeStream(session->stream);
        aclrtDestroyStream(session->stream);
        aclrtDestroyContext(session->context);
    }
    free(session);
}

static int device_buffer_new(void *handle, const void *source, size_t bytes, void **result) {
    ascend_session *session = handle;
    aclError status = aclrtSetCurrentContext(session->context);
    if (status != ACL_SUCCESS) return status;
    void *allocation = NULL;
    status = aclrtMalloc(&allocation, bytes, ACL_MEM_MALLOC_NORMAL_ONLY);
    if (status != ACL_SUCCESS) return status;
    if (source) {
        status = aclrtMemcpy(allocation, bytes, source, bytes, ACL_MEMCPY_HOST_TO_DEVICE);
        if (status != ACL_SUCCESS) {
            aclrtFree(allocation);
            return status;
        }
    }
    *result = allocation;
    return ACL_SUCCESS;
}

static void device_buffer_free(void *handle, void *buffer) {
    ascend_session *session = handle;
    if (buffer && aclrtSetCurrentContext(session->context) == ACL_SUCCESS) {
        aclrtSynchronizeStream(session->stream);
        aclrtFree(buffer);
    }
}

static int device_buffer_read(void *handle, const void *buffer, void *destination, size_t bytes) {
    ascend_session *session = handle;
    aclError status = aclrtSetCurrentContext(session->context);
    if (status != ACL_SUCCESS) return status;
    return aclrtMemcpy(destination, bytes, buffer, bytes, ACL_MEMCPY_DEVICE_TO_HOST);
}

int plait_w4a16_launch(const plait_w4a16_shape *s,
                       const uint16_t *a, const uint8_t *w, const uint16_t *scale, const uint8_t *zero,
                       const uint16_t *bias, void *out, void *stream) {
    if (!plait_w4a16_valid_shape(s) || !a || !w || !scale || !zero || !out) {
        return ACL_ERROR_INVALID_PARAM;
    }
    return aclrtlaunch_plait_ascend_w4a16(
        1, stream, (void *)a, (void *)w, (void *)scale, (void *)zero,
        (void *)(bias ? bias : scale), out, s->m, s->n, s->k, s->group_size,
        s->output_bits, bias != NULL);
}

static int completion_new(ascend_session *session, ascend_completion **result) {
    aclError status = aclrtSetCurrentContext(session->context);
    if (status != ACL_SUCCESS) return status;
    ascend_completion *value = calloc(1, sizeof(*value));
    if (!value) return ACL_ERROR_BAD_ALLOC;
    status = aclrtCreateEvent(&value->event);
    if (status != ACL_SUCCESS) {
        free(value);
        return status;
    }
    *result = value;
    return ACL_SUCCESS;
}

static int complete_submission(ascend_session *session, ascend_completion *value,
                               aclError status, void **result) {
    if (status == ACL_SUCCESS) status = aclrtRecordEvent(value->event, session->stream);
    if (status == ACL_SUCCESS) {
        *result = value;
        return ACL_SUCCESS;
    }
    aclrtSynchronizeStream(session->stream);
    if (value->workspace) aclrtFree(value->workspace);
    aclrtDestroyEvent(value->event);
    free(value);
    return status;
}

static int device_launch(void *handle, const plait_w4a16_shape *s,
                         const void *a, const void *w, const void *scale,
                         const void *zero, const void *bias, void *out, void **result) {
    ascend_session *session = handle;
    ascend_completion *completion = NULL;
    aclError status = completion_new(session, &completion);
    if (status != ACL_SUCCESS) return status;
    status = plait_w4a16_launch(s, a, w, scale, zero, bias, out, session->stream);
    return complete_submission(session, completion, status, result);
}

#if defined(PLAIT_ASCEND_INTEGER_CUBE)
typedef struct {
    uint32_t m, n, k, groups;
    size_t a_bytes, b_bytes, bytes;
} cube_plan;

static size_t align_workspace(size_t bytes) {
    const size_t alignment = PLAIT_ASCEND_WORKSPACE_ALIGNMENT;
    return (bytes + alignment - 1) & ~(alignment - 1);
}

static bool make_cube_plan(const plait_w4a16_shape *s, cube_plan *plan) {
    const uint32_t active_k = s->k < s->group_size ? s->k : s->group_size;
    if (active_k > PLAIT_ASCEND_MAX_GROUP_K) return false;
    const uint64_t groups = plait_ceil_div(s->k, s->group_size);
    const uint64_t m = (uint64_t)plait_ceil_div(s->m, PLAIT_ASCEND_TILE_M) * PLAIT_ASCEND_TILE_M;
    const uint64_t n = (uint64_t)plait_ceil_div(s->n, PLAIT_ASCEND_TILE_N) * PLAIT_ASCEND_TILE_N;
    const uint32_t k = plait_ceil_div(active_k, PLAIT_ASCEND_CUBE_K) * PLAIT_ASCEND_CUBE_K;
    const uint64_t bytes_per_group = (m + n) * k + m * n * sizeof(int32_t);
    const uint64_t max_workspace = 64u * 1024 * 1024;
    if (bytes_per_group > (max_workspace - 3 * PLAIT_ASCEND_WORKSPACE_ALIGNMENT) / groups) return false;
    *plan = (cube_plan){
        (uint32_t)m, (uint32_t)n, k, (uint32_t)groups,
        align_workspace((size_t)(groups * m * k)),
        align_workspace((size_t)(groups * n * k)),
        (size_t)(groups * m * n * sizeof(int32_t)),
    };
    return true;
}

static uint32_t block_count(uint32_t cores, uint64_t units) {
    return units < cores ? (uint32_t)units : cores;
}

int plait_w4_quantize_f16_v1(
    void *handle, uint32_t rows, uint32_t columns, uint32_t group_size, uint32_t bits,
    const void *input, void *codes, void *scales, void *invalid, void **result) {
    const plait_w4a16_shape shape = {rows, 1, columns, group_size, 16};
    if (!plait_w4_quantized_valid_shape(&shape, bits) || (uint64_t)rows * columns > UINT32_MAX ||
        !handle || !input || !codes || !scales || !invalid || !result) return ACL_ERROR_INVALID_PARAM;
    ascend_session *session = handle;
    ascend_completion *completion = NULL;
    aclError status = completion_new(session, &completion);
    if (status != ACL_SUCCESS) return status;

    const uint64_t scale_bytes = (uint64_t)rows * plait_ceil_div(columns, group_size) * sizeof(float);
    const uint32_t stride = bits == 4 ? plait_ceil_div(columns, 2) : columns;
    const uint64_t code_bytes = (uint64_t)rows * stride;
    status = aclrtlaunch_plait_ascend_quantize_scales(
        block_count(session->vector_cores, 2 + (scale_bytes - 1) / PLAIT_ASCEND_DCACHE_LINE_BYTES),
        session->stream, (void *)input, scales, rows, columns, group_size, bits);
    if (status == ACL_SUCCESS) {
        status = aclrtlaunch_plait_ascend_quantize_pack(
            block_count(session->vector_cores, 2 + (code_bytes - 1) / PLAIT_ASCEND_DCACHE_LINE_BYTES),
            session->stream, (void *)input, scales, codes, invalid, rows, columns, group_size, bits);
    }
    return complete_submission(session, completion, status, result);
}

int plait_w4_quantized_launch_v1(
    void *handle, const plait_w4a16_shape *s, uint32_t bits, const void *a, const void *as,
    const void *w, const void *ws, const void *zero, const void *bias, void *out, void **result) {
    if (!plait_w4_quantized_valid_shape(s, bits) || !handle || !a || !as || !w || !ws ||
        !zero || !out || !result) return ACL_ERROR_INVALID_PARAM;
    ascend_session *session = handle;
    ascend_completion *completion = NULL;
    aclError status = completion_new(session, &completion);
    if (status != ACL_SUCCESS) return status;

    void *scratch = out;
    cube_plan plan;
    const bool use_cube = make_cube_plan(s, &plan);
    if (use_cube) {
        status = aclrtMalloc(&completion->workspace, plan.a_bytes + plan.b_bytes + plan.bytes +
                             (PLAIT_ASCEND_WORKSPACE_ALIGNMENT - 1),
                             ACL_MEM_MALLOC_NORMAL_ONLY);
        if (status == ACL_SUCCESS) {
            uint8_t *packed_a = (uint8_t *)align_workspace((uintptr_t)completion->workspace);
            uint8_t *packed_b = packed_a + plan.a_bytes;
            scratch = packed_b + plan.b_bytes;
            const uint32_t blocks = block_count(session->vector_cores,
                1 + (plan.a_bytes + plan.b_bytes) / PLAIT_ASCEND_WORKSPACE_ALIGNMENT);
            status = aclrtlaunch_plait_ascend_pack_w4(
                blocks, session->stream, (void *)a, (void *)w, (void *)zero, packed_a, packed_b,
                s->m, s->n, s->k, s->group_size, plan.m, plan.n, plan.k, bits);
            if (status == ACL_SUCCESS) {
                const uint64_t tiles = (uint64_t)plan.groups * (plan.m / PLAIT_ASCEND_TILE_M) *
                                       (plan.n / PLAIT_ASCEND_TILE_N);
                status = aclrtlaunch_plait_ascend_w4_cube(
                    block_count(session->cube_cores, tiles), session->stream,
                    packed_a, packed_b, scratch, plan.m, plan.n, plan.k, plan.groups);
            }
        }
    }
    if (status == ACL_SUCCESS) {
        const uint64_t output_bytes = (uint64_t)s->m * s->n * (s->output_bits / 8);
        status = aclrtlaunch_plait_ascend_finish_w4(
            block_count(session->vector_cores, 2 + (output_bytes - 1) / PLAIT_ASCEND_WORKSPACE_ALIGNMENT),
            session->stream,
            (void *)a, (void *)as, (void *)w, (void *)ws, (void *)zero,
            (void *)(bias ? bias : ws), scratch, out,
            s->m, s->n, s->k, s->group_size, bits, s->output_bits, bias != NULL, use_cube);
    }
    return complete_submission(session, completion, status, result);
}
#endif

static int device_wait(void *handle, void *value) {
    ascend_session *session = handle;
    ascend_completion *completion = value;
    aclError status = aclrtSetCurrentContext(session->context);
    if (status == ACL_SUCCESS) status = aclrtSynchronizeEvent(completion->event);
    if (status == ACL_SUCCESS && completion->workspace && aclrtFree(completion->workspace) == ACL_SUCCESS) {
        completion->workspace = NULL;
    }
    return status;
}

static void device_completion_free(void *handle, void *value) {
    ascend_session *session = handle;
    ascend_completion *completion = value;
    if (!completion) return;
    if (aclrtSetCurrentContext(session->context) == ACL_SUCCESS) {
        if (completion->workspace) {
            if (aclrtSynchronizeEvent(completion->event) != ACL_SUCCESS) {
                aclrtSynchronizeStream(session->stream);
            }
            aclrtFree(completion->workspace);
        }
        aclrtDestroyEvent(completion->event);
    }
    free(completion);
}

static const plait_w4a16_device_api api = {
    device_open, device_close, device_buffer_new, device_buffer_free,
    device_buffer_read, device_launch, device_wait, device_completion_free,
};

const plait_w4a16_device_api *plait_w4a16_device_api_v1(void) {
    return &api;
}

int plait_w4_completion_query_v1(void *handle, void *value, uint32_t *ready) {
    if (!handle || !value || !ready) return ACL_ERROR_INVALID_PARAM;
    ascend_session *session = handle;
    ascend_completion *completion = value;
    aclError status = aclrtSetCurrentContext(session->context);
    if (status != ACL_SUCCESS) return status;
    aclrtEventRecordedStatus recorded;
    status = aclrtQueryEventStatus(completion->event, &recorded);
    if (status != ACL_SUCCESS) return status;
    *ready = recorded == ACL_EVENT_RECORDED_STATUS_COMPLETE;
    return ACL_SUCCESS;
}

int plait_w4a16_run_host(const plait_w4a16_shape *s, int ordinal,
                         const uint16_t *a, const uint8_t *w, const uint16_t *scale,
                         const uint8_t *zero, const uint16_t *bias, void *out) {
    if (!plait_w4a16_valid_shape(s) || !a || !w || !scale || !zero || !out) {
        return ACL_ERROR_INVALID_PARAM;
    }
    const size_t groups = (size_t)s->n * plait_ceil_div(s->k, s->group_size);
    const size_t output_bytes = (size_t)s->m * s->n * (s->output_bits / 8);
    const void *host[] = {a, w, scale, zero, bias, NULL};
    const size_t sizes[] = {
        (size_t)s->m * s->k * 2, (size_t)s->n * plait_ceil_div(s->k, 2),
        groups * 2, groups, (size_t)s->n * 2, output_bytes,
    };
    void *buffers[6] = {0};
    void *event = NULL;
    void *session = NULL;
    aclError status = device_open(ordinal, &session);
    if (status != ACL_SUCCESS) return status;
    for (size_t i = 0; i < 6 && status == ACL_SUCCESS; ++i) {
        if (i == 4 && !bias) continue;
        status = device_buffer_new(session, host[i], sizes[i], &buffers[i]);
    }
    if (status == ACL_SUCCESS) {
        status = device_launch(session, s, buffers[0], buffers[1], buffers[2], buffers[3],
                               buffers[4], buffers[5], &event);
    }
    if (status == ACL_SUCCESS) status = device_wait(session, event);
    if (status == ACL_SUCCESS) status = device_buffer_read(session, buffers[5], out, output_bytes);
    device_completion_free(session, event);
    for (size_t i = 0; i < 6; ++i) device_buffer_free(session, buffers[i]);
    device_close(session);
    return status;
}
